mod audio;mod game;mod video;
use game::Game;
fn main(){let mut out=vec![];for flags in 0..4 {let mut g=Game::new(false).unwrap();g.memory.fill(0);g.memory[0x720]=0x96;g.memory[0x710]=120;g.memory[0x560]=120;g.memory[0x6b0]=255;g.memory[0x6a0]=flags;g.memory[0x6c0]=if flags==1{8}else{0};let mut samples=vec![];for tick in 0..400 {g.memory[0x1a]=tick as u8;g.actor_call(0x9922,0).unwrap();samples.push(serde_json::json!({"tick":tick,"sprite":g.memory[0x500],"palette":g.memory[0x540],"flip_x":g.memory[0x6a]&64!=0,"x":g.memory[0x710] as f32+g.memory[0x6f0] as f32*256.+g.memory[0x5c0] as f32/256.,"y":g.memory[0x560] as f32+g.memory[0x700] as f32*256.+g.memory[0x580] as f32/256.,"state":g.memory[0x520],"timer":g.memory[0x6d0],"heading":g.memory[0x6c0]}));}out.push(serde_json::json!({"flags":flags,"samples":samples}));}println!("{}",serde_json::to_string_pretty(&out).unwrap());}
